"use client"

import { forwardRef, useId, useImperativeHandle, type ReactNode } from "react"

import { useCardInput, type UseCardInputOptions } from "./use-card-input"

export type CardLayout = "stacked" | "single"

export interface CardInputProps extends UseCardInputOptions {
  /** Visible label. Supply this or `aria-label` — a field with neither has no accessible name. */
  label?: ReactNode
  /** Helper text under the field. Replaced by the error message while one is showing. */
  hint?: ReactNode
  /** `stacked` is three fields; `single` is one row, Stripe-style. */
  layout?: CardLayout
  /** Field names for native submission. */
  expiryName?: string
  cvcName?: string
}

export const CardInput = forwardRef<HTMLInputElement, CardInputProps>(
  function CardInput(
    { label, hint, layout = "stacked", expiryName, cvcName, className, id: idProp, ...rest },
    ref,
  ) {
    const reactId = useId()
    const id = idProp ?? reactId

    const api = useCardInput({ ...rest, id })
    const {
      numberProps,
      expiryProps,
      cvcProps,
      ariaProps,
      containerProps,
      hiddenInputProps,
      ownsErrorUI,
      errorText,
      errorId,
      visible,
      brand,
      expiry,
      cvc,
    } = api

    useImperativeHandle(
      ref,
      () =>
        numberProps.ref.current ??
        ({ focus: () => numberProps.ref.current?.focus() } as HTMLInputElement),
      [numberProps.ref],
    )

    const invalid = ariaProps["aria-invalid"] ? "true" : undefined

    return (
      <div className={`inputcn-field ${className ?? ""}`.trim()} {...containerProps}>
        {label === undefined ? null : (
          <label className="inputcn-label" htmlFor={id}>
            {label}
          </label>
        )}

        {layout === "single" ? (
          <div className="inputcn-cc-single" data-invalid={invalid}>
            <input
              {...numberProps}
              {...ariaProps}
              id={id}
              className="inputcn-cc-number"
              aria-label={rest["aria-label"] ?? "Card number"}
            />
            {brand ? (
              <span className="inputcn-brand" aria-hidden="true">
                {brand.label}
              </span>
            ) : null}
            <span className="inputcn-cc-rule" aria-hidden="true" />
            <input {...expiryProps} className="inputcn-cc-exp" aria-label="Expiry date" />
            <span className="inputcn-cc-rule" aria-hidden="true" />
            <input {...cvcProps} className="inputcn-cc-cvc" aria-label="Security code" />
          </div>
        ) : (
          <>
            <div className="inputcn-group" data-invalid={invalid}>
              <input
                {...numberProps}
                {...ariaProps}
                id={id}
                className="inputcn-bare inputcn-numeric"
                aria-label={rest["aria-label"] ?? "Card number"}
              />
              <span className="inputcn-affix inputcn-affix-right inputcn-brand" aria-hidden="true">
                {brand?.label ?? ""}
              </span>
            </div>

            <div className="inputcn-cc-row">
              <div>
                <label className="inputcn-label" htmlFor={`${id}-exp`}>
                  Expiry
                </label>
                <input
                  {...expiryProps}
                  id={`${id}-exp`}
                  className="inputcn-input inputcn-numeric"
                />
              </div>
              <div>
                <label className="inputcn-label" htmlFor={`${id}-cvc`}>
                  CVC
                </label>
                <input
                  {...cvcProps}
                  id={`${id}-cvc`}
                  className="inputcn-input inputcn-numeric"
                />
              </div>
            </div>
          </>
        )}

        {ownsErrorUI && errorText ? (
          <p
            id={errorId}
            className={visible?.warning ? "inputcn-warning" : "inputcn-error"}
            // Stable rule name so a test can assert WHICH rule failed rather
            // than matching copy, which breaks on a rewrite or a locale change.
            data-rule={visible?.rule}
            role="alert"
          >
            {errorText}
          </p>
        ) : hint !== undefined ? (
          <p className="inputcn-hint">{hint}</p>
        ) : null}

        {hiddenInputProps ? <input {...hiddenInputProps} /> : null}
        {expiryName ? <input type="hidden" name={expiryName} value={expiry} readOnly /> : null}
        {cvcName ? <input type="hidden" name={cvcName} value={cvc} readOnly /> : null}
      </div>
    )
  },
)

"use client"

import { useCallback, useMemo, useRef, useState, type ClipboardEvent } from "react"

import { clipboardText } from "@inputcn/core/paste"
import type { BaseFieldProps, Rule } from "@inputcn/core/types"
import { useField, type UseFieldResult } from "@inputcn/core/use-field"
import { useMaskedValue } from "@inputcn/core/use-masked-value"
import { custom, required as requiredRule, rules } from "@inputcn/core/validity"

import {
  detectBrand,
  formatCard,
  formatExpiry,
  isExpired,
  isValidLength,
  luhn,
  maxLengthOf,
  parseExpiry,
  parsePastedCard,
  UNKNOWN_BRAND,
  type BrandSpec,
  type CardBrand,
} from "./card"

export interface CardConstraints {
  /** Restrict to the brands your PSP actually accepts. */
  brands?: readonly CardBrand[]
  /** Reject a card whose expiry has passed. Requires an expiry value. */
  notExpired?: boolean
  /** Require the CVC to be filled to the brand's length. */
  requireCvc?: boolean
}

export interface UseCardInputOptions
  extends BaseFieldProps<string>,
    CardConstraints {
  /** Expiry as typed, e.g. "04 / 28". Controlled separately from the number. */
  expiry?: string
  defaultExpiry?: string
  onExpiryChange?: (value: string) => void
  cvc?: string
  defaultCvc?: string
  onCvcChange?: (value: string) => void
}

export interface UseCardInputResult extends UseFieldResult<string> {
  brand: BrandSpec | undefined
  /** Never undefined — falls back to a neutral 4-4-4-4 layout. */
  layout: BrandSpec
  expiry: string
  cvc: string
  numberProps: {
    ref: React.RefObject<HTMLInputElement | null>
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    defaultValue: string
    onPaste: (e: ClipboardEvent<HTMLInputElement>) => void
    inputMode: "numeric"
    autoComplete: "cc-number"
    placeholder: string
    disabled: boolean | undefined
    readOnly: boolean | undefined
  }
  expiryProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    inputMode: "numeric"
    autoComplete: "cc-exp"
    placeholder: string
    disabled: boolean | undefined
    readOnly: boolean | undefined
  }
  cvcProps: {
    ref: React.RefObject<HTMLInputElement | null>
    value: string
    onChange: (e: React.ChangeEvent<HTMLInputElement>) => void
    inputMode: "numeric"
    autoComplete: "cc-csc"
    placeholder: string
    maxLength: number
    disabled: boolean | undefined
    readOnly: boolean | undefined
  }
}

const EMPTY = ""

export function useCardInput(options: UseCardInputOptions): UseCardInputResult {
  const {
    brands,
    notExpired,
    requireCvc,
    expiry: expiryProp,
    defaultExpiry,
    onExpiryChange,
    cvc: cvcProp,
    defaultCvc,
    onCvcChange,
    required,
    validate,
    disabled,
    readOnly,
    ...base
  } = options

  const expiryRef = useRef<HTMLInputElement | null>(null)
  const cvcRef = useRef<HTMLInputElement | null>(null)

  /* ---------------- expiry & cvc: controlled or not ---------------- */

  const [expiryState, setExpiryState] = useState(defaultExpiry ?? EMPTY)
  const expiry = expiryProp ?? expiryState
  const setExpiry = useCallback(
    (v: string) => {
      if (disabled || readOnly) return
      if (expiryProp === undefined) setExpiryState(v)
      onExpiryChange?.(v)
    },
    [disabled, readOnly, expiryProp, onExpiryChange],
  )

  const [cvcState, setCvcState] = useState(defaultCvc ?? EMPTY)
  const cvc = cvcProp ?? cvcState
  const setCvc = useCallback(
    (v: string) => {
      if (disabled || readOnly) return
      if (cvcProp === undefined) setCvcState(v)
      onCvcChange?.(v)
    },
    [disabled, readOnly, cvcProp, onCvcChange],
  )

  /* ---------------- brand ---------------- */

  const allowed = useMemo(
    () => (brands ? new Set<CardBrand>(brands) : null),
    [brands],
  )

  /* ---------------- rules ---------------- */

  const brandLabels = useMemo(
    () =>
      brands
        ? brands.map((b) => b.charAt(0).toUpperCase() + b.slice(1)).join(", ")
        : "",
    [brands],
  )

  const ruleList = useMemo<ReadonlyArray<Rule<string>>>(
    () =>
      rules<string>(
        requiredRule<string>(required),
        {
          rule: "cardLength",
          test: (v) => isValidLength(v, detectBrand(v)),
        },
        { rule: "luhn", test: (v) => luhn(v) },
        allowed && {
          rule: "cardBrand",
          params: { brands: brandLabels },
          test: (v) => {
            const b = detectBrand(v)
            return !b || allowed.has(b.brand)
          },
        },
        notExpired && {
          rule: "cardExpired",
          // The number's validity should not depend on a field the user may
          // not have reached yet, so an unparseable expiry is not an error
          // here — `required` on the expiry is the right tool for that.
          test: () => !isExpired(parseExpiry(expiry)),
        },
        requireCvc && {
          rule: "required",
          params: { message: "Enter the security code" },
          test: (v) => cvc.length === (detectBrand(v) ?? UNKNOWN_BRAND).cvcLength,
        },
        custom<string>(validate),
      ),
    [required, allowed, brandLabels, notExpired, expiry, requireCvc, cvc, validate],
  )

  const field = useField<string>({
    component: "CardInput",
    emptyValue: EMPTY,
    rules: ruleList,
    ...base,
    required,
    disabled,
    readOnly,
  })

  const { value, setValue } = field

  const brand = useMemo(() => detectBrand(value), [value])
  const layout = brand ?? UNKNOWN_BRAND

  /* ---------------- the number itself ---------------- */

  const format = useCallback((raw: string) => formatCard(raw, detectBrand(raw)), [])

  const parse = useCallback((text: string) => {
    const d = text.replace(/\D/g, "")
    return d.slice(0, maxLengthOf(detectBrand(d)))
  }, [])

  const masked = useMaskedValue<string>({
    value,
    format,
    parse,
    onChange: (next) => {
      setValue(next)
      // Advance when the number is both a valid length AND passes Luhn.
      //
      // Length alone is wrong: Visa accepts 16, 18 and 19 digits, so a
      // 19-digit card would have focus yanked away at digit 16. Requiring
      // Luhn too means a 16-digit prefix of a longer card almost never
      // advances, while a genuine 16-digit card always does.
      if (isValidLength(next, detectBrand(next)) && luhn(next)) {
        expiryRef.current?.focus()
      }
    },
    disabled,
    readOnly,
  })

  const onNumberPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      if (disabled || readOnly) return
      const text = clipboardText(e)
      if (!text) return
      e.preventDefault()
      setValue(parse(parsePastedCard(text)))
    },
    [disabled, readOnly, setValue, parse],
  )

  const onExpiryInput = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const raw = e.currentTarget.value
      const next = formatExpiry(raw)
      setExpiry(next)
      if (next.replace(/\D/g, "").length === 4) cvcRef.current?.focus()
    },
    [setExpiry],
  )

  const onCvcInput = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setCvc(e.currentTarget.value.replace(/\D/g, "").slice(0, layout.cvcLength))
    },
    [setCvc, layout.cvcLength],
  )

  const numberProps = useMemo(
    () => ({
      ...masked.inputProps,
      onPaste: onNumberPaste,
      inputMode: "numeric" as const,
      autoComplete: "cc-number" as const,
      placeholder: formatCard("4".repeat(maxLengthOf(layout)), layout).replace(/4/g, "0"),
      disabled,
      readOnly,
    }),
    [masked.inputProps, onNumberPaste, layout, disabled, readOnly],
  )

  return {
    ...field,
    brand,
    layout,
    expiry,
    cvc,
    numberProps,
    expiryProps: {
      ref: expiryRef,
      value: expiry,
      onChange: onExpiryInput,
      inputMode: "numeric" as const,
      autoComplete: "cc-exp" as const,
      placeholder: "MM / YY",
      disabled,
      readOnly,
    },
    cvcProps: {
      ref: cvcRef,
      value: cvc,
      onChange: onCvcInput,
      inputMode: "numeric" as const,
      autoComplete: "cc-csc" as const,
      placeholder: layout.cvcLength === 4 ? "1234" : "123",
      maxLength: layout.cvcLength,
      disabled,
      readOnly,
    },
  }
}

/**
 * Payment card parsing and validation. Framework-free.
 *
 * Canonical value is the digits only: `"4242424242424242"`.
 *
 * Scope note: this validates STRUCTURE — brand, length, Luhn checksum, expiry.
 * It cannot tell you whether a card has funds or even exists; only your PSP
 * can. The point is to catch the typo before the user watches a spinner and
 * gets a decline.
 */

import { digitsOf, scrub } from "@inputcn/core/paste"

export type CardBrand =
  | "visa"
  | "mastercard"
  | "amex"
  | "discover"
  | "diners"
  | "jcb"
  | "unionpay"
  | "maestro"

export interface BrandSpec {
  brand: CardBrand
  label: string
  /** Digit groups for display, e.g. Amex is 4-6-5. */
  gaps: readonly number[]
  /** Accepted total lengths. */
  lengths: readonly number[]
  cvcLength: number
  test: RegExp
}

// Hoisted — matched on every keystroke.
export const BRANDS: readonly BrandSpec[] = [
  { brand: "visa", label: "Visa", gaps: [4, 4, 4, 4], lengths: [16, 18, 19], cvcLength: 3, test: /^4/ },
  { brand: "mastercard", label: "Mastercard", gaps: [4, 4, 4, 4], lengths: [16], cvcLength: 3, test: /^(5[1-5]|2[2-7])/ },
  { brand: "amex", label: "American Express", gaps: [4, 6, 5], lengths: [15], cvcLength: 4, test: /^3[47]/ },
  { brand: "diners", label: "Diners Club", gaps: [4, 6, 4], lengths: [14, 16, 19], cvcLength: 3, test: /^3(?:0[0-5]|[68])/ },
  { brand: "discover", label: "Discover", gaps: [4, 4, 4, 4], lengths: [16, 19], cvcLength: 3, test: /^6(?:011|5|4[4-9])/ },
  { brand: "jcb", label: "JCB", gaps: [4, 4, 4, 4], lengths: [16, 17, 18, 19], cvcLength: 3, test: /^35(?:2[89]|[3-8])/ },
  { brand: "unionpay", label: "UnionPay", gaps: [4, 4, 4, 4], lengths: [16, 17, 18, 19], cvcLength: 3, test: /^62/ },
  { brand: "maestro", label: "Maestro", gaps: [4, 4, 4, 4], lengths: [12, 13, 14, 15, 16, 17, 18, 19], cvcLength: 3, test: /^(5018|5020|5038|6304|6759|676[1-3])/ },
]

/** Fallback used while the number is too short to identify. */
export const UNKNOWN_BRAND: BrandSpec = {
  brand: "visa", // never surfaced; only its layout is used
  label: "",
  gaps: [4, 4, 4, 4],
  lengths: [16],
  cvcLength: 3,
  test: /^$/,
}

const BY_BRAND = new Map(BRANDS.map((b) => [b.brand, b]))

export function brandSpec(brand: CardBrand): BrandSpec | undefined {
  return BY_BRAND.get(brand)
}

/** Identify the brand from a partial number. `undefined` until determinable. */
export function detectBrand(digits: string): BrandSpec | undefined {
  if (!digits) return undefined
  // Maestro's ranges overlap Mastercard's, so it is tested first.
  for (const b of BRANDS) {
    if (b.test.test(digits)) return b
  }
  return undefined
}

/** Longest number this brand can hold. */
export function maxLengthOf(spec: BrandSpec | undefined): number {
  const s = spec ?? UNKNOWN_BRAND
  let n = 0
  for (const l of s.lengths) if (l > n) n = l
  return n
}

/**
 * Luhn checksum. Catches single-digit typos and most transpositions — which is
 * the overwhelming majority of what users actually get wrong.
 */
export function luhn(digits: string): boolean {
  if (digits.length < 12) return false
  let sum = 0
  let alternate = false
  for (let i = digits.length - 1; i >= 0; i--) {
    let n = digits.charCodeAt(i) - 48
    if (n < 0 || n > 9) return false
    if (alternate) {
      n *= 2
      if (n > 9) n -= 9
    }
    sum += n
    alternate = !alternate
  }
  return sum % 10 === 0
}

/** True when the length is one this brand accepts. */
export function isValidLength(digits: string, spec: BrandSpec | undefined): boolean {
  return (spec ?? UNKNOWN_BRAND).lengths.includes(digits.length)
}

/** Format for display using the brand's own grouping. */
export function formatCard(digits: string, spec: BrandSpec | undefined): string {
  const s = spec ?? UNKNOWN_BRAND
  const capped = digits.slice(0, maxLengthOf(s))
  if (!capped) return ""

  const out: string[] = []
  let i = 0
  for (const gap of s.gaps) {
    if (i >= capped.length) break
    out.push(capped.slice(i, i + gap))
    i += gap
  }
  // Anything past the declared groups (19-digit Visa) trails in fours.
  while (i < capped.length) {
    out.push(capped.slice(i, i + 4))
    i += 4
  }
  return out.join(" ")
}

/* ------------------------------------------------------------------ *
 * Expiry
 * ------------------------------------------------------------------ */

export interface Expiry {
  month: number
  year: number
  /** Four-digit year. */
  fullYear: number
}

/** Parse `"0428"`, `"04/28"`, `"04 / 2028"` into month and year. */
export function parseExpiry(input: string): Expiry | null {
  const d = digitsOf(input)
  if (d.length < 3) return null

  const month = Number(d.slice(0, 2))
  if (month < 1 || month > 12) return null

  const yearDigits = d.slice(2, 6)
  const year = Number(yearDigits)
  if (!Number.isFinite(year)) return null

  // A two-digit year is this century; four digits are taken literally.
  const fullYear = yearDigits.length <= 2 ? 2000 + year : year
  return { month, year, fullYear }
}

export function formatExpiry(input: string): string {
  const d = digitsOf(input).slice(0, 4)
  if (d.length <= 2) return d
  return `${d.slice(0, 2)} / ${d.slice(2)}`
}

/**
 * True when the card has not expired.
 * A card is valid through the LAST day of its stated month, so the comparison
 * is against the first day of the following month.
 */
export function isExpired(expiry: Expiry | null, now = new Date()): boolean {
  if (!expiry) return false
  const expiresAfter = new Date(expiry.fullYear, expiry.month, 1)
  return now.getTime() >= expiresAfter.getTime()
}

/* ------------------------------------------------------------------ *
 * Paste
 * ------------------------------------------------------------------ */

/** Extract a card number from pasted text, however it was punctuated. */
export function parsePastedCard(input: string): string {
  return digitsOf(scrub(input)).slice(0, 19)
}
